<?php
namespace App\Services;use App\Models\PosSale;use App\Models\PosSyncBatch;use Illuminate\Support\Facades\DB;
class PosSyncService{public function sync(array $data,int $userId,PosService $pos):PosSyncBatch{return DB::transaction(function()use($data,$userId,$pos){$batch=PosSyncBatch::firstOrCreate(['batch_uuid'=>$data['batch_uuid']],['user_id'=>$userId,'device_id'=>$data['device_id'],'received_count'=>count($data['sales'])]);if($batch->result)return $batch;$accepted=0;$conflicts=0;$result=[];foreach($data['sales'] as $sale){if($existing=PosSale::where('client_uuid',$sale['client_uuid'])->first()){$result[]=['client_uuid'=>$sale['client_uuid'],'status'=>'duplicate','sale_id'=>$existing->id];continue;}try{$created=$pos->sell($sale,$userId);$created->update(['client_uuid'=>$sale['client_uuid']]);$accepted++;$result[]=['client_uuid'=>$sale['client_uuid'],'status'=>'accepted','sale_id'=>$created->id];}catch(\Throwable $e){$conflicts++;$batch->conflicts()->create(['client_uuid'=>$sale['client_uuid'],'type'=>'sale_rejected','message'=>$e->getMessage(),'payload'=>$sale]);$result[]=['client_uuid'=>$sale['client_uuid'],'status'=>'conflict'];}}$batch->update(['accepted_count'=>$accepted,'conflict_count'=>$conflicts,'result'=>$result]);return $batch->fresh('conflicts');},3);}}
